    id: "hyper-text",
    name: "Hyper Text",
    title: "乱码解密文字",
    category: "Text",
    suiteId: "kinetic-typography",
    description: "文字先显示快速变化的随机字符，再从左到右依次变成真实文字，鼠标悬停可重新播放。",
    componentFilename: "HyperText.vue",
    componentCode: "<script setup lang=\"ts\">\nimport { ref, onMounted, watch } from 'vue'\nimport { cn } from '@/lib/utils'\n\ninterface HyperTextProps {\n  text: string\n  duration?: number\n  class?: string\n  triggerOnHover?: boolean\n}\n\nconst props = withDefaults(defineProps<HyperTextProps>(), {\n  text: 'AURA_DECRYPT_V1',\n  duration: 800,\n  triggerOnHover: true,\n})\n\nconst alphabets = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+'\nconst displayText = ref(props.text)\nlet animTimer: ReturnType<typeof setInterval> | null = null\n\nfunction scramble() {\n  if (animTimer) clearInterval(animTimer)\n\n  const original = props.text\n  let iteration = 0\n  const maxIterations = original.length\n\n  const stepTime = Math.max(25, props.duration / (maxIterations * 2))\n\n  animTimer = setInterval(() => {\n    displayText.value = original\n      .split('')\n      .map((char, index) => {\n        if (char === ' ') return ' '\n        if (index < iteration) {\n          return original[index]\n        }\n        return alphabets[Math.floor(Math.random() * alphabets.length)]\n      })\n      .join('')\n\n    if (iteration >= maxIterations) {\n      if (animTimer) clearInterval(animTimer)\n      displayText.value = original\n    }\n\n    iteration += 1 / 2\n  }, stepTime)\n}\n\nfunction handleMouseEnter() {\n  if (props.triggerOnHover) {\n    scramble()\n  }\n}\n\nonMounted(() => {\n  scramble()\n})\n\nwatch(() => props.text, () => {\n  scramble()\n})\n\ndefineExpose({\n  trigger: scramble,\n})\n</script>\n\n<template>\n  <span\n    :class=\"\n      cn(\n        'inline-block font-mono font-bold tracking-wider select-none cursor-pointer transition-colors',\n        'text-zinc-900 dark:text-zinc-100 hover:text-emerald-500 dark:hover:text-emerald-400',\n        props.class\n      )\n    \"\n    @mouseenter=\"handleMouseEnter\"\n  >\n    {{ displayText }}\n  </span>\n</template>\n",
    usageCode: "<script setup lang=\"ts\">\nimport HyperText from '@/components/ui/HyperText.vue'\n</script>\n\n<template>\n  <div class=\"p-6\">\n    <HyperText text=\"AURA_PROTOCOL_ACTIVE\" :duration=\"800\" class=\"text-3xl text-emerald-500 font-mono\" />\n  </div>\n</template>",
    propsList: [
      {
            "name": "text",
            "type": "string",
            "default": "'AURA_DECRYPT_V1'",
            "description": "最终解密还原的目标明文字符串"
      },
      {
            "name": "duration",
            "type": "number",
            "default": "800",
            "description": "完整解密动画周期时长 (ms)"
      },
      {
            "name": "triggerOnHover",
            "type": "boolean",
            "default": "true",
            "description": "是否在鼠标悬停时自动重新触发解密"
      }
],
