    suiteId: "kinetic-typography",
    description: "大量粒子组成文字，鼠标靠近时粒子被推散，离开后重新聚拢。",
    componentFilename: "CursorDrivenParticleTypography.vue",
    componentCode: "<template>\n  <div\n    ref=\"containerRef\"\n    class=\"relative w-full h-full min-h-[300px] flex items-center justify-center overflow-hidden rounded-2xl bg-neutral-950 select-none\"\n    :class=\"className\"\n    @mousemove=\"handleMouseMove\"\n    @mouseleave=\"handleMouseLeave\"\n  >\n    <canvas ref=\"canvasRef\" class=\"block w-full h-full pointer-events-none\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, onMounted, onUnmounted, watch } from 'vue'\n\ninterface Props {\n  text?: string\n  fontSize?: number\n  fontFamily?: string\n  particleSize?: number\n  particleDensity?: number\n  dispersionStrength?: number\n  returnSpeed?: number\n  color?: string\n  className?: string\n}\n\nconst props = withDefaults(defineProps<Props>(), {\n  text: 'AURA UI',\n  fontSize: 100,\n  fontFamily: 'system-ui, sans-serif',\n  particleSize: 1.6,\n  particleDensity: 5,\n  dispersionStrength: 18,\n  returnSpeed: 0.08,\n  color: '#38bdf8',\n  className: '',\n})\n\ninterface Particle {\n  x: number\n  y: number\n  originX: number\n  originY: number\n  vx: number\n  vy: number\n}\n\nconst containerRef = ref<HTMLDivElement | null>(null)\nconst canvasRef = ref<HTMLCanvasElement | null>(null)\n\nlet particles: Particle[] = []\nlet mouseX = -1000\nlet mouseY = -1000\nlet animationFrameId = 0\nlet resizeObserver: ResizeObserver | null = null\n\nfunction handleMouseMove(e: MouseEvent) {\n  if (!canvasRef.value) return\n  const rect = canvasRef.value.getBoundingClientRect()\n  mouseX = e.clientX - rect.left\n  mouseY = e.clientY - rect.top\n}\n\nfunction handleMouseLeave() {\n  mouseX = -1000\n  mouseY = -1000\n}\n\nfunction initParticles() {\n  const canvas = canvasRef.value\n  const container = containerRef.value\n  if (!canvas || !container) return\n  const ctx = canvas.getContext('2d', { willReadFrequently: true })\n  if (!ctx) return\n\n  const rect = container.getBoundingClientRect()\n  const dpr = Math.min(window.devicePixelRatio || 1, 2)\n  canvas.width = Math.floor(rect.width * dpr)\n  canvas.height = Math.floor(rect.height * dpr)\n  canvas.style.width = `${rect.width}px`\n  canvas.style.height = `${rect.height}px`\n\n  ctx.scale(dpr, dpr)\n  ctx.clearRect(0, 0, rect.width, rect.height)\n\n  const effectiveFontSize = Math.min(props.fontSize, rect.width * 0.14)\n  ctx.font = `bold ${effectiveFontSize}px ${props.fontFamily}`\n  ctx.textAlign = 'center'\n  ctx.textBaseline = 'middle'\n  ctx.fillStyle = '#ffffff'\n  ctx.fillText(props.text, rect.width / 2, rect.height / 2)\n\n  const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height)\n  particles = []\n\n  const step = Math.max(1, Math.floor(props.particleDensity * dpr))\n  for (let y = 0; y < imgData.height; y += step) {\n    for (let x = 0; x < imgData.width; x += step) {\n      const idx = (y * imgData.width + x) * 4\n      const alpha = imgData.data[idx + 3] || 0\n      if (alpha > 128) {\n        const posX = x / dpr\n        const posY = y / dpr\n        particles.push({\n          x: posX + (Math.random() - 0.5) * 8,\n          y: posY + (Math.random() - 0.5) * 8,\n          originX: posX,\n          originY: posY,\n          vx: (Math.random() - 0.5) * 4,\n          vy: (Math.random() - 0.5) * 4,\n        })\n      }\n    }\n  }\n}\n\nfunction animate() {\n  const canvas = canvasRef.value\n  const container = containerRef.value\n  if (!canvas || !container) return\n  const ctx = canvas.getContext('2d')\n  if (!ctx) return\n\n  const dpr = Math.min(window.devicePixelRatio || 1, 2)\n  ctx.save()\n  ctx.scale(dpr, dpr)\n  ctx.clearRect(0, 0, container.clientWidth, container.clientHeight)\n\n  const radius = 110\n  ctx.fillStyle = props.color\n\n  for (let i = 0; i < particles.length; i++) {\n    const p = particles[i]!\n    const dx = mouseX - p.x\n    const dy = mouseY - p.y\n    const dist = Math.hypot(dx, dy)\n\n    if (dist < radius && mouseX > -500) {\n      const force = (radius - dist) / radius\n      p.vx -= (dx / dist) * force * props.dispersionStrength\n      p.vy -= (dy / dist) * force * props.dispersionStrength\n    }\n\n    // Spring back\n    p.vx += (p.originX - p.x) * props.returnSpeed\n    p.vy += (p.originY - p.y) * props.returnSpeed\n    p.vx *= 0.84\n    p.vy *= 0.84\n\n    p.x += p.vx\n    p.y += p.vy\n\n    ctx.beginPath()\n    ctx.arc(p.x, p.y, props.particleSize, 0, Math.PI * 2)\n    ctx.fill()\n  }\n\n  ctx.restore()\n  animationFrameId = requestAnimationFrame(animate)\n}\n\nwatch(() => [props.text, props.fontSize, props.color], initParticles)\n\nonMounted(() => {\n  initParticles()\n  if (containerRef.value) {\n    resizeObserver = new ResizeObserver(initParticles)\n    resizeObserver.observe(containerRef.value)\n  }\n  animationFrameId = requestAnimationFrame(animate)\n})\n\nonUnmounted(() => {\n  cancelAnimationFrame(animationFrameId)\n  if (resizeObserver) resizeObserver.disconnect()\n})\n</script>\n",
    usageCode: "<script setup lang=\"ts\">\nimport CursorDrivenParticleTypography from \"@/components/ui/CursorDrivenParticleTypography.vue\"\n</script>\n\n<template>\n  <CursorDrivenParticleTypography />\n</template>",
